                          const catIds = category.engines.map(e => e.id);
                          setSelectedEngines(prev => {
                            const others = prev.filter(id => !catIds.includes(id));
                            const allInCat = catIds.every(id => prev.includes(id));
                            return allInCat ? others : [...new Set([...prev, ...catIds])];
                          });
